(1,'8129b126-b8a6-47a6-81f8-dcd443fc9374','{\n  \"name\": \"Covid 19\",\n  \"description\": \"Covid 19 Form\",\n  \"version\": \"1\",\n  \"published\": true,\n  \"retired\": false,\n  \"encounter\": \"Consultation\",\n  \"processor\": \"EncounterFormProcessor\",\n  \"referencedForms\": [],\n  \"pages\": [\n    {\n      \"label\": \"Covid 19 Signs and Symptoms\",\n      \"sections\": [\n        {\n          \"label\": \"Covid 19 Signs and Symptoms\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"label\": \"Covid 19 Set\",\n              \"type\": \"obsGroup\",\n              \"questionOptions\": {\n                \"rendering\": \"group\",\n                \"concept\": \"464d8752-45f8-4a25-8972-772cbc52efbe\"\n              },\n              \"id\": \"Covid_19_sx\",\n              \"questions\": [\n                {\n                  \"label\": \"Covid 19 Signs and Symptoms in past 14 days\",\n                  \"id\": \"__I2HM7pMys\",\n                  \"questionOptions\": {\n                    \"rendering\": \"checkbox\",\n                    \"concept\": \"0eaa21e0-5f69-41a9-9dea-942796590bbb\",\n                    \"answers\": [\n                      {\n                        \"label\": \"Congestion\",\n                        \"concept\": \"30e2da8f-34ca-4c93-94c8-d429f22d381c\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Cough\",\n                        \"concept\": \"143264AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Sneezing\",\n                        \"concept\": \"2395de62-f5a6-49b6-ab0f-57a21a9029c1\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Fever\",\n                        \"concept\": \"140238AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Sore throat or pain with swallowing\",\n                        \"concept\": \"2c75944e-5fc5-4d9d-b389-fe878fde38e3\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Shortness of breath\",\n                        \"concept\": \"141600AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Loss of taste\",\n                        \"concept\": \"135588AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Loss of smell\",\n                        \"concept\": \"c1fb49bd-0ca5-43ae-bf8d-df35e73c34ea\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Diarrhea, Vomiting or Abdominal pain\",\n                        \"concept\": \"87b3f6a1-6d79-4923-9485-200dfd937782\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Practicing social distancing\",\n                        \"concept\": \"64fb3f91-08d8-4a3b-92ba-16655e834b1c\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Rash, nonvesicular, unspec.\",\n                        \"concept\": \"2134b7e3-4e15-11e4-8a57-0800271c1b75\",\n                        \"conceptMappings\": []\n                      }\n                    ]\n                  },\n                  \"type\": \"obs\"\n                },\n                {\n                  \"label\": \"Onset Date\",\n                  \"id\": \"__tyxtEosu2\",\n                  \"questionOptions\": {\n                    \"rendering\": \"date\",\n                    \"concept\": \"81a50873-81c8-4c2e-8892-b2cd635b704c\"\n                  },\n                  \"type\": \"obs\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Covid 19 Test\",\n      \"sections\": [\n        {\n          \"label\": \"Covid 19 Test\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"label\": \"Covid 19 Test\",\n              \"type\": \"obsGroup\",\n              \"questionOptions\": {\n                \"rendering\": \"group\",\n                \"concept\": \"4c2a4b12-becc-4429-a94d-b78e06699d0f\"\n              },\n              \"id\": \"Covid_19_Test\",\n              \"questions\": [\n                {\n                  \"label\": \"Tested for COVID 19\",\n                  \"id\": \"__5GxrFGLFo\",\n                  \"questionOptions\": {\n                    \"rendering\": \"select\",\n                    \"concept\": \"89c5bc03-8ce2-40d8-a77d-20b5a62a1ca1\",\n                    \"answers\": [\n                      {\n                        \"label\": \"Yes\",\n                        \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"No\",\n                        \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      }\n                    ]\n                  },\n                  \"type\": \"obs\"\n                },\n                {\n                  \"label\": \"Test Done\",\n                  \"id\": \"__HxGzEo8nL\",\n                  \"questionOptions\": {\n                    \"rendering\": \"select\",\n                    \"concept\": \"611190b4-2b83-42c5-bbb1-8d99bfaec9ed\",\n                    \"answers\": [\n                      {\n                        \"label\": \"Respiratory PCR\",\n                        \"concept\": \"efe34fae-de1e-4430-86ac-3198d0fb4a70\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Rapid blood test\",\n                        \"concept\": \"7149a26d-c0a7-42c4-86ae-099616830831\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"ELISA blood test\",\n                        \"concept\": \"c1cc178c-390c-4194-b286-f9c57e0f313d\",\n                        \"conceptMappings\": []\n                      }\n                    ]\n                  },\n                  \"type\": \"obs\"\n                },\n                {\n                  \"label\": \"Test Results\",\n                  \"id\": \"__L42EMuowp\",\n                  \"questionOptions\": {\n                    \"rendering\": \"select\",\n                    \"concept\": \"192f67ac-247c-4e1d-966a-4c223e33d38b\",\n                    \"answers\": [\n                      {\n                        \"label\": \"Positive\",\n                        \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      },\n                      {\n                        \"label\": \"Negative\",\n                        \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                        \"conceptMappings\": []\n                      }\n                    ]\n                  },\n                  \"type\": \"obs\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}'),
(2,'8f45df43-4b78-476b-9aad-e342769cac84','{\n  \"name\": \"Form Engine Cookbook\",\n  \"description\": \"Reference examples of the OpenMRS 3 form engine\'s features. Each page demonstrates one topic, with a short markdown explanation followed by working example fields. Not for clinical use; this form is deliberately unpublished so it does not appear in the patient chart.\",\n  \"version\": \"1\",\n  \"published\": false,\n  \"retired\": false,\n  \"encounter\": \"Consultation\",\n  \"processor\": \"EncounterFormProcessor\",\n  \"pages\": [\n    {\n      \"label\": \"Introduction\",\n      \"sections\": [\n        {\n          \"label\": \"About this form\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"cookbookIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"## Form Engine Cookbook\\n\\nA working reference for the patterns supported by the OpenMRS 3 form engine. Each page covers one authoring task â€” making a field appear conditionally, requiring a value when something else is answered, computing a value from other fields, and so on â€” with a short explanation followed by fields that exercise the pattern.\\n\\nOpen the JSON to copy the shape of any example into your own form. Most fields use real concepts from the reference-app demo metadata so the form renders end-to-end in a dev distro.\\n\\nThis form is `published: false` by design. It will not appear in the patient chart unless you flip that flag for local testing.\"\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Conditional visibility\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"visibilityIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want a field to appear only when another answer is set** â€” for example, a follow-up question that is only relevant after a specific symptom is selected, or a pregnancy section that should only show for a female patient of reproductive age.\\n\\nUse **`hide.hideWhenExpression`** to hide a field while a condition is true. The condition is a small JavaScript snippet with access to:\\n\\n- any other question on the form, by its `id`\\n- the patient\'s `sex` and `age` (always available)\\n- helpers such as `isEmpty(value)`, `arrayContains(list, value)`\\n\\n```json\\n\\\"hide\\\": { \\\"hideWhenExpression\\\": \\\"isEmpty(symptomChoice) || symptomChoice !== \'OTHER_UUID\'\\\" }\\n```\\n\\nUse **`disabled.disableWhenExpression`** when you want the field visible but not interactive â€” e.g. greyed out until a prerequisite field is answered. Use **`isDisabled: true`** for a field that is always disabled (rare; usually you want one of the expressions above).\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"Hide when expression\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"isPregnantAnchor\",\n              \"label\": \"Is the patient pregnant?\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"5272AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              }\n            },\n            {\n              \"id\": \"eddWhenPregnant\",\n              \"label\": \"Expected date of delivery\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"5596AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              },\n              \"hide\": {\n                \"hideWhenExpression\": \"isEmpty(isPregnantAnchor) || isPregnantAnchor !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"Disable when expression\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"pregnancyNotes\",\n              \"label\": \"Pregnancy notes (disabled until the anchor above is answered)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"textarea\",\n                \"concept\": \"160531AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              },\n              \"disabled\": {\n                \"disableWhenExpression\": \"isEmpty(isPregnantAnchor)\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"Static isDisabled\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"alwaysDisabled\",\n              \"label\": \"Read-only informational field (always disabled)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"text\",\n                \"concept\": \"160221AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              },\n              \"isDisabled\": true\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Required variants\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"requiredIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want a field to be mandatory** â€” sometimes always, sometimes only under specific conditions. The `required` property covers all three cases:\\n\\n1. **Always required** â€” set `\\\"required\\\": true`. Use this when the field must be answered for the form to be valid, no exceptions.\\n\\n2. **Required only sometimes** â€” set `\\\"required\\\"` to a JavaScript expression string. The field becomes required only while the expression is true. Same expression scope as `hide`.\\n\\n   ```json\\n   \\\"required\\\": \\\"isEmpty(reasonForVisit) === false\\\"\\n   ```\\n\\n3. **Required when another field has a specific answer** â€” set `\\\"required\\\"` to an object with `type: \\\"conditionalAnswered\\\"`. Useful when downstream questions are mandatory once an upstream answer is picked (e.g. a safety-plan flow where every \\\"Yes\\\" branch must be filled in).\\n\\n   ```json\\n   \\\"required\\\": {\\n     \\\"type\\\": \\\"conditionalAnswered\\\",\\n     \\\"referenceQuestionId\\\": \\\"hasRiskFactors\\\",\\n     \\\"referenceQuestionAnswers\\\": [\\\"YES_UUID\\\"]\\n   }\\n   ```\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"Boolean required\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"visitTypeRequired\",\n              \"label\": \"Visit type (required)\",\n              \"type\": \"obs\",\n              \"required\": true,\n              \"questionOptions\": {\n                \"rendering\": \"select\",\n                \"concept\": \"164181AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"160530AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"New client\"\n                  },\n                  {\n                    \"concept\": \"160563AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Revisit\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"Expression-based required\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"travelHistoryAnchor\",\n              \"label\": \"History of recent travel?\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"165656AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              }\n            },\n            {\n              \"id\": \"travelDestination\",\n              \"label\": \"Travel destination (required only when travel history is Yes)\",\n              \"type\": \"obs\",\n              \"required\": \"travelHistoryAnchor === \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\",\n              \"questionOptions\": {\n                \"rendering\": \"textarea\",\n                \"concept\": \"160531AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"conditionalAnswered object\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"hivStatus\",\n              \"label\": \"HIV status\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Positive\"\n                  },\n                  {\n                    \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Negative\"\n                  },\n                  {\n                    \"concept\": \"1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Unknown\"\n                  }\n                ]\n              }\n            },\n            {\n              \"id\": \"hivDiagnosisDate\",\n              \"label\": \"Date of HIV diagnosis (required when HIV status is Positive)\",\n              \"type\": \"obs\",\n              \"required\": {\n                \"type\": \"conditionalAnswered\",\n                \"message\": \"Required when HIV status is Positive\",\n                \"referenceQuestionId\": \"hivStatus\",\n                \"referenceQuestionAnswers\": [\n                  \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n                ]\n              },\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"160554AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Validators\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"validatorsIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want the engine to reject a value beyond just \\\"is it filled in\\\"** â€” for example, a temperature outside a plausible range, a date in the future when it shouldn\'t be, or a field that must be filled in once another field has a particular answer.\\n\\nAdd a `validators` array to the field. Each entry is an object with a `type`. The built-in validators:\\n\\n- **`js_expression`** â€” flag the field when an expression is true. Accepts `failsWhenExpression`, optional `message` (custom error) and `warningMessage` (lighter, non-blocking variant). Best for cross-field rules and numeric ranges.\\n\\n  ```json\\n  { \\\"type\\\": \\\"js_expression\\\", \\\"failsWhenExpression\\\": \\\"myValue > 200\\\", \\\"message\\\": \\\"Heart rate looks too high\\\" }\\n  ```\\n\\n- **`date`** â€” reject invalid dates; pass `allowFutureDates: \'false\'` to also reject future dates.\\n\\n- **`conditionalAnswered`** â€” fail when this field is empty and another field has a specific answer. Same shape as the conditional `required` above, just surfaced as a validator (the user sees an error rather than a silent requirement flip).\\n\\n- **`default_value`** â€” catch authoring mistakes: fails when a `defaultValue` set on the field isn\'t valid for the concept (e.g. a value that isn\'t in the coded answer list).\\n\\nA field can carry several validators; the engine runs them all and surfaces every failure.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"js_expression validator\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"monthsSinceHivTest\",\n              \"label\": \"Months since HIV test (warns if > 24)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"163191AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"min\": \"0\",\n                \"max\": \"240\"\n              },\n              \"validators\": [\n                {\n                  \"type\": \"js_expression\",\n                  \"failsWhenExpression\": \"myValue > 24\",\n                  \"warningMessage\": \"HIV test older than 24 months; consider repeating\"\n                }\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"date validator\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"onsetDate\",\n              \"label\": \"Onset date (future dates not allowed)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"159948AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              },\n              \"validators\": [\n                {\n                  \"type\": \"date\",\n                  \"allowFutureDates\": \"false\"\n                }\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"conditionalAnswered validator\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"travelAnchorForValidator\",\n              \"label\": \"History of recent travel?\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"165656AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              }\n            },\n            {\n              \"id\": \"travelDurationDays\",\n              \"label\": \"Travel duration in days (validator-enforced when travel = Yes)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"1731AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"min\": \"1\"\n              },\n              \"validators\": [\n                {\n                  \"type\": \"conditionalAnswered\",\n                  \"message\": \"Travel duration is expected when travel history is Yes\",\n                  \"referenceQuestionId\": \"travelAnchorForValidator\",\n                  \"referenceQuestionAnswers\": [\n                    \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n                  ]\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Computed fields\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"computedIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want one field to be computed from others** â€” BMI from height and weight, expected delivery date from a last-menstrual-period date, age from date of birth, days-since-onset from an onset date.\\n\\nSet `questionOptions.calculate.calculateExpression` to a JavaScript expression. The engine re-evaluates it whenever a referenced field changes and writes the result into this field.\\n\\n```json\\n\\\"questionOptions\\\": {\\n  \\\"rendering\\\": \\\"number\\\",\\n  \\\"concept\\\": \\\"<bmi-concept-uuid>\\\",\\n  \\\"calculate\\\": { \\\"calculateExpression\\\": \\\"calcBMI(height, weight)\\\" }\\n}\\n```\\n\\nInside the expression you have a domain-helper library (`calcBMI`, `calcEDD`, `calcAgeBasedOnDate`, `calcBSA`, `calcMonthsOnART`, `calcGravida`, the z-score family `calcWeightForHeightZscore` / `calcBMIForAgeZscore` / `calcHeightForAgeZscore`) plus general helpers (`today()`, `isDateBefore`, `isDateAfter`, `addDaysToDate`, `addWeeksToDate`, `arrayContains`, `arrayContainsAny`, `isEmpty`, `formatDate`, `parseDate`).\\n\\nRefer to other fields by their `id`; the engine substitutes the current value at evaluation time.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"BMI from weight and height\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"weight\",\n              \"label\": \"Weight (kg)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5089AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"min\": \"0\",\n                \"max\": \"250\",\n                \"step\": 0.1\n              }\n            },\n            {\n              \"id\": \"height\",\n              \"label\": \"Height (cm)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5090AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"min\": \"10\",\n                \"max\": \"272\",\n                \"step\": 0.1\n              }\n            },\n            {\n              \"id\": \"bmi\",\n              \"label\": \"BMI (computed)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"1342AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"disallowDecimals\": false,\n                \"calculate\": {\n                  \"calculateExpression\": \"calcBMI(height, weight)\"\n                }\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"EDD from LMP\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"lmp\",\n              \"label\": \"Last menstrual period\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"1427AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              },\n              \"validators\": [\n                {\n                  \"type\": \"date\",\n                  \"allowFutureDates\": \"false\"\n                }\n              ]\n            },\n            {\n              \"id\": \"computedEdd\",\n              \"label\": \"Expected date of delivery (computed)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"5596AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"calculate\": {\n                  \"calculateExpression\": \"calcEDD(lmp)\"\n                }\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Previous-value and historical\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"prevValueIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want the form to surface what was captured for this patient last time** â€” either as a starting point the user can override, or as the default when the field is left blank.\\n\\nThree complementary controls cover this:\\n\\n- **`formOptions.usePreviousValueDisabled`** at the form root. When `true`, the per-question \\\"copy previous value\\\" affordance is hidden everywhere on the form. Default is `false` (the affordance shows on every applicable question). Set to `true` when prior values would be misleading (e.g. an acute-care form).\\n\\n- **`questionOptions.enablePreviousValue`** at the question level. An explicit per-field opt-in for showing the prior value as a fill hint. Use this to bring the affordance back on a single field after disabling it form-wide.\\n\\n- **`field.historicalExpression`** â€” pre-fills the field automatically when the form opens, by walking the patient\'s encounter history. Most common shape:\\n\\n  ```json\\n  \\\"historicalExpression\\\": \\\"_.isEmpty(HD.getObject(\'prevEnc\').getValue(\'<concept-uuid>\')) ? undefined : HD.getObject(\'prevEnc\').getValue(\'<concept-uuid>\')\\\"\\n  ```\\n\\n  The `HD` helper exposes prior encounters; the snippet above pulls the most recent observation for a given concept.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"enablePreviousValue (question-level opt-in)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"weightForPrev\",\n              \"label\": \"Weight (kg) â€” previous-value hint enabled\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5089AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"enablePreviousValue\": true,\n                \"min\": \"0\",\n                \"max\": \"250\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"historicalExpression (pre-fill from prior encounter)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"hivStatusWithHistory\",\n              \"label\": \"HIV status (pre-filled from most recent prior encounter)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Positive\"\n                  },\n                  {\n                    \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Negative\"\n                  },\n                  {\n                    \"concept\": \"1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Unknown\"\n                  }\n                ]\n              },\n              \"historicalExpression\": \"_.isEmpty(HD.getObject(\'prevEnc\').getValue(\'159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')) ? undefined : HD.getObject(\'prevEnc\').getValue(\'159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Special renderings\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"renderingsIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want a control other than the standard text/number/date/radio/checkbox/select** â€” for cases where one of those would technically work but a more specialised widget reads better.\\n\\nThe engine ships several extras:\\n\\n- **`toggle`** â€” a yes/no switch backed by a coded concept. Customise the labels with `toggleOptions.labelTrue` / `labelFalse`. Best when the field is binary and a checkbox would feel ambiguous.\\n\\n- **`content-switcher`** â€” a Carbon ContentSwitcher for a small set of answers (typically 2â€“5). Reads as segmented buttons; saves a click compared to a dropdown for short lists.\\n\\n- **`fixed-value`** â€” writes a preset value without showing any control. Useful for capturing a default like an encounter sub-type that the user never picks.\\n\\n- **`select-concept-answers`** â€” a dropdown whose options come from the concept\'s coded-answer set on the server. Saves you from enumerating answers in the schema, at the cost of a server fetch.\\n\\n- **`extension-widget`** â€” embeds a named O3 extension slot inside the form. Use when a separate module contributes a widget (e.g. a summary card) that needs to live in the form\'s flow.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"toggle\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"recentTravelToggle\",\n              \"label\": \"Recent travel?\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"toggle\",\n                \"concept\": \"165656AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"toggleOptions\": {\n                  \"labelTrue\": \"Yes\",\n                  \"labelFalse\": \"No\"\n                }\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"content-switcher\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"hivStatusContentSwitch\",\n              \"label\": \"HIV status\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"content-switcher\",\n                \"concept\": \"159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Positive\"\n                  },\n                  {\n                    \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Negative\"\n                  },\n                  {\n                    \"concept\": \"1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Unknown\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"fixed-value\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"visitTypeFixed\",\n              \"label\": \"Visit type (fixed to \'New client\')\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"fixed-value\",\n                \"concept\": \"164181AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"defaultValue\": \"160530AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"select-concept-answers\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"hivStatusFromConceptAnswers\",\n              \"label\": \"HIV status (answer options read from the concept\'s answer set)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"select-concept-answers\",\n                \"concept\": \"159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"extension-widget\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"patientBannerExtension\",\n              \"label\": \"Embedded extension slot\",\n              \"questionOptions\": {\n                \"rendering\": \"extension-widget\",\n                \"extensionId\": \"patient-banner\",\n                \"extensionSlotName\": \"patient-banner-slot\"\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Special field types\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"fieldTypesIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want the field to save somewhere other than an observation** â€” to a patient identifier, a person attribute, a lab order, or a program workflow state.\\n\\nThe engine maps each `type` to a different OpenMRS domain object at submission time:\\n\\n- **`patientIdentifier`** â€” writes a patient identifier of the specified `identifierType`. Useful for capturing or updating MRNs and other registration identifiers from inside a clinical form.\\n\\n- **`personAttribute`** â€” writes a person attribute of the specified `attributeType`. Useful for non-identifier demographics like preferred-language or telephone-number.\\n\\n- **`testOrder`** â€” emits a lab order under the configured `orderType` and `orderSettingUuid`. The orders the user can pick come from `selectableOrders`.\\n\\n- **`programState`** â€” moves the patient to a different state in a program workflow. Requires the `programUuid` and `workflowUuid` of the enrolment.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"patientIdentifier\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"openmrsIdField\",\n              \"label\": \"OpenMRS ID\",\n              \"type\": \"patientIdentifier\",\n              \"questionOptions\": {\n                \"rendering\": \"text\",\n                \"identifierType\": \"05a29f94-c0ed-11e2-94be-8c13b969e334\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"personAttribute\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"phoneNumberField\",\n              \"label\": \"Phone number\",\n              \"type\": \"personAttribute\",\n              \"questionOptions\": {\n                \"rendering\": \"text\",\n                \"attributeType\": \"14d4f066-15f5-102d-96e4-000c29c2a5d7\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"testOrder\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"labOrders\",\n              \"label\": \"Lab orders\",\n              \"type\": \"testOrder\",\n              \"questionOptions\": {\n                \"rendering\": \"repeating\",\n                \"orderSettingUuid\": \"6f0c9a92-6f24-11e3-af88-005056821db0\",\n                \"orderType\": \"testorder\",\n                \"selectableOrders\": [\n                  {\n                    \"concept\": \"5497AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"CD4\"\n                  },\n                  {\n                    \"concept\": \"856AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Viral load\"\n                  },\n                  {\n                    \"concept\": \"1015AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Hemoglobin\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"programState\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"programStateExplainer\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"A `programState` field changes the patient\'s workflow state inside a program enrolment. The shape is:\\n\\n```json\\n{\\n  \\\"id\\\": \\\"hivWorkflowState\\\",\\n  \\\"label\\\": \\\"HIV treatment status\\\",\\n  \\\"type\\\": \\\"programState\\\",\\n  \\\"questionOptions\\\": {\\n    \\\"rendering\\\": \\\"select\\\",\\n    \\\"programUuid\\\": \\\"<program-uuid>\\\",\\n    \\\"workflowUuid\\\": \\\"<workflow-uuid>\\\"\\n  }\\n}\\n```\\n\\nThe engine fetches the workflow\'s possible states from the backend at render time, so the field can only be exercised against a distro that has the program and workflow loaded. The cookbook documents the shape rather than embedding a live field, since the form-builder preview has no enrolment context to render against.\"\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Form-level metadata\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"formMetaIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want behaviour that lives at the form level rather than on a single field** â€” different modes the form can open in, things to run after a successful save, embedded translations.\\n\\nThese root-level options cover those needs:\\n\\n- **`availableIntents`** â€” named modes the form can open in (e.g. \\\"first-visit\\\" vs \\\"follow-up\\\"). The active intent is passed to every field, so individual fields can adapt.\\n\\n- **`behaviours`** (on a field) â€” per-intent overrides that swap out the field\'s `required`, `hide`, or `disabled` for a given intent. Lets one form schema serve multiple use cases.\\n\\n- **`postSubmissionActions`** â€” actions that run after a successful save (e.g. enroll the patient in a program, schedule a follow-up visit). Each entry has an `actionId` matching a registered action and an optional `enabled` JS expression.\\n\\n- **`translations`** â€” a flat key-to-translation map embedded directly in the form. An alternative to the separate `ampathformstranslations/` files Iniz supports.\\n\\n- **`meta.programs`** â€” flags the form as program-aware so the engine loads the patient\'s enrolment context.\\n\\n- **`defaultPage`**, **`allowUnspecifiedAll`** â€” form-wide defaults.\\n\\nScroll to the root of this JSON to see all of the above set. The field below illustrates a `behaviours` override.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"Per-intent behaviours\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"eligibilityScreen\",\n              \"label\": \"Eligibility screen\",\n              \"type\": \"obs\",\n              \"required\": false,\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"164181AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"answers\": [\n                  {\n                    \"concept\": \"160530AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"New client\"\n                  },\n                  {\n                    \"concept\": \"160563AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Revisit\"\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"COOKBOOK_BASELINE\",\n                  \"required\": true\n                },\n                {\n                  \"intent\": \"COOKBOOK_FOLLOWUP\",\n                  \"required\": false,\n                  \"hide\": {\n                    \"hideWhenExpression\": \"true\"\n                  }\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Composition\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"compositionIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**You want to reuse content across multiple forms** â€” share a \\\"Vitals\\\" snippet between every consultation form, or compose a multi-encounter workflow without duplicating fields.\\n\\nTwo patterns cover this:\\n\\n- **Section `reference`** â€” a section in this form pulls its questions from a section in another form. Good for sharing snippets across forms (vitals, demographics) without copy-paste.\\n\\n- **Page `isSubform` + `subform`** â€” a page embeds an entire other form inline. The inner form submits its own encounter; the outer form acts as a container. Good for forms that need to capture multiple sibling encounters in one go.\\n\\nBoth patterns render via the chart-side pipeline at runtime, so the form-builder preview can only show their structure, not a live composed render. The pages below document each shape.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"Reference pattern (how it looks in a real form)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"referencePatternExplainer\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"In a real form you\'d reference a section from another form by declaring `referencedForms` at the root and then using `section.reference` to pull it in. The section\'s `questions` array is ignored when `reference` is set; the engine fills it from the target form at load time.\\n\\n```json\\n// at form root\\n\\\"referencedForms\\\": [\\n  { \\\"formName\\\": \\\"Form Engine Cookbook Library\\\", \\\"alias\\\": \\\"lib\\\" }\\n]\\n\\n// on any section\\n{\\n  \\\"label\\\": \\\"Vitals snippet (referenced)\\\",\\n  \\\"isExpanded\\\": \\\"true\\\",\\n  \\\"reference\\\": {\\n    \\\"form\\\": \\\"lib\\\",\\n    \\\"page\\\": \\\"Vitals\\\",\\n    \\\"section\\\": \\\"Vitals snippet\\\"\\n  },\\n  \\\"questions\\\": []\\n}\\n```\\n\\nThe companion file `form-engine-cookbook-library-core_demo.json` is the target form, so once Iniz imports it the pattern works end-to-end. The section below renders the same vitals inline so you can see them without loading the library.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"Vitals snippet (inline, equivalent to the reference)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"compositionWeight\",\n              \"label\": \"Weight (kg)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5089AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"min\": \"0\",\n                \"max\": \"250\",\n                \"step\": 0.1\n              }\n            },\n            {\n              \"id\": \"compositionHeight\",\n              \"label\": \"Height (cm)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5090AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"min\": \"10\",\n                \"max\": \"272\",\n                \"step\": 0.1\n              }\n            },\n            {\n              \"id\": \"compositionTemperature\",\n              \"label\": \"Temperature\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5088AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"min\": \"25\",\n                \"max\": \"43\",\n                \"step\": 0.1\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Subform pattern\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"subformPatternExplainer\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"A page can declare `isSubform: true` and embed an entire form schema under `subform.form`. The engine treats that nested schema as a self-contained form that submits its own encounter using the `processor`, `encounterType`, and `uuid` declared on the subform.\\n\\n```json\\n{\\n  \\\"label\\\": \\\"Subform page\\\",\\n  \\\"isSubform\\\": true,\\n  \\\"subform\\\": {\\n    \\\"name\\\": \\\"Vitals subform\\\",\\n    \\\"form\\\": {\\n      \\\"name\\\": \\\"Vitals subform\\\",\\n      \\\"pages\\\": [ /* ...nested pages with their own sections and questions... */ ],\\n      \\\"processor\\\": \\\"EncounterFormProcessor\\\",\\n      \\\"uuid\\\": \\\"<subform-form-uuid>\\\",\\n      \\\"encounterType\\\": \\\"<subform-encounter-type-uuid>\\\"\\n    }\\n  },\\n  \\\"sections\\\": []\\n}\\n```\\n\\nUse this when you need a sibling encounter created alongside the parent encounter (e.g. a vitals encounter inside a consultation form). The subform\'s fields don\'t need top-level `meta` initialization in the parent form schema; the engine wires them up via its subform pipeline at runtime in the patient chart.\\n\\nThis cookbook intentionally documents the pattern instead of embedding a working subform: the form-builder preview renders subforms via the chart-side pipeline, so a live subform can only be exercised in a real distro. The Composition page above already shows the inline-vitals shape that a subform would otherwise compose.\"\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Question-option grab bag\",\n      \"sections\": [\n        {\n          \"label\": \"About\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"qoGrabBagIntro\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**A sweep of the remaining `questionOptions` keys the engine recognises.** Each section below demonstrates one key in isolation, so you can see the shape and decide whether it\'s the right fit for a real form.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"orientation (radio layout)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"horizontalRadio\",\n              \"label\": \"HIV status (horizontal radio)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"orientation\": \"horizontal\",\n                \"answers\": [\n                  {\n                    \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Positive\"\n                  },\n                  {\n                    \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Negative\"\n                  },\n                  {\n                    \"concept\": \"1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Unknown\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"locationTag (filter location picker)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"admitLocation\",\n              \"label\": \"Admission location\",\n              \"type\": \"encounterLocation\",\n              \"questionOptions\": {\n                \"rendering\": \"ui-select-extended\",\n                \"locationTag\": \"Admission Location\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"weeksList (gestational weeks helper, reserved)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"weeksListExplainer\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"value\": [\n                \"**`questionOptions.weeksList`** is declared in the engine\'s schema types as a hint for gestational-age pickers (e.g. `weeksList: [4, 8, 12, ...]`), but no current renderer reads it. Treat it as reserved: setting it has no effect today.\\n\\nFor gestational age, prefer a `number` rendering with `min` / `max`, or a `select` with explicit `answers` if you want a fixed picker.\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"shownDateOptions (attach a date to an obs)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"symptomWithDate\",\n              \"label\": \"Primary symptom (with onset date)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"select\",\n                \"concept\": \"5219AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"showDate\": \"true\",\n                \"shownDateOptions\": {\n                  \"validators\": [\n                    {\n                      \"type\": \"date\",\n                      \"allowFutureDates\": \"false\"\n                    }\n                  ]\n                },\n                \"answers\": [\n                  {\n                    \"concept\": \"121375AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Headache\"\n                  },\n                  {\n                    \"concept\": \"121AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Abdominal pain\"\n                  },\n                  {\n                    \"concept\": \"122496AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Cough\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"showComment (attach a comment to an obs)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"hivStatusWithComment\",\n              \"label\": \"HIV status (with comment field)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"159576AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"showComment\": \"true\",\n                \"answers\": [\n                  {\n                    \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Positive\"\n                  },\n                  {\n                    \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Negative\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"diagnosis (rank, concept set)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"primaryDiagnosis\",\n              \"label\": \"Primary diagnosis\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"problem\",\n                \"concept\": \"161602AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"diagnosis\": {\n                  \"rank\": 1,\n                  \"isConfirmed\": true,\n                  \"conceptClasses\": [\n                    \"Diagnosis\"\n                  ],\n                  \"conceptSet\": \"160170AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\n                }\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"allowMultiple + isSearchable\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"multiMedications\",\n              \"label\": \"Current medications (multiple, searchable)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"drug\",\n                \"concept\": \"1193AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"allowMultiple\": true,\n                \"isSearchable\": true\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"isCheckboxSearchable\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"id\": \"searchableCheckbox\",\n              \"label\": \"Findings (searchable checkbox group)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"checkbox-searchable\",\n                \"concept\